1	/**
2	 * Read-only knowledge sources.
3	 *
4	 * A `Source` pulls new items from wherever the business's knowledge already flows.
5	 * The cursor is an OPAQUE string owned by each adapter (the framework only stores
6	 * and hands it back), so adapters choose their own resumability scheme. Cursors
7	 * are persisted under `.ost-agent/state/<adapter>.json` inside the vault so they
8	 * survive restarts and travel in git.
9	 */
10	import fs from "node:fs";
11	import path from "node:path";
12	import { CHANNEL_NAME_PATTERN } from "../config/schema.js";
13	
14	/**
15	 * Who produced an evidence record — a closed vocabulary, one entry per channel.
16	 *
17	 * Closed, and not a free string, because the next thing to be keyed on this identity
18	 * is a trust ledger with a ceiling per actor kind, and `web-trust.ts` is already the
19	 * cautionary tale: `rankHost` accepts any string, so a commissioned pipeline and a
20	 * real hostname share one namespace and one ceiling (B6). A union means a new adapter
21	 * cannot quietly mint a producer identity by typing a new word — it has to be added
22	 * here, where the ceiling will eventually be written next to it.
23	 *
24	 * {@link UNKNOWN_ACTOR} is a member because a record can predate the stamp or carry a
25	 * hand-edited value, and the read has to land somewhere; it lands on the least-trusted
26	 * answer, never on a channel's name.
27	 */
28	export const ACTORS = ["inbox", "slack", "atlassian", "usage", "transcript", "actions", "unknown"] as const;
29	export type Actor = (typeof ACTORS)[number];
30	
31	/** The fail-closed answer: a record whose producer is not established. */
32	export const UNKNOWN_ACTOR: Actor = "unknown";
33	
34	export function isActor(value: unknown): value is Actor {
35	  return typeof value === "string" && (ACTORS as readonly string[]).includes(value);
36	}
37	
38	/**
39	 * One fetched item, before it is stored.
40	 *
41	 * **There is deliberately no `actor` field here.** The producer identity is not part
42	 * of the payload — it is stamped at the ingest site from the {@link Source} that did
43	 * the fetching (`writeEvidence`'s third argument). An item that can carry an actor is
44	 * an item whose author can choose one, and the author of an inbox body is the
45	 * untrusted builder.
46	 */
47	export interface EvidenceItem {
48	  /** Stable id within the source. */
49	  id: string;
50	  /** Provenance tag, e.g. "INBOX:note.md", "JIRA:PROJ-1234". */
51	  source: string;
52	  title: string;
53	  /** Untrusted text — treated as data, never as instructions. */
54	  body: string;
55	  /** ISO timestamp. */
56	  timestamp: string;
57	  url?: string;
58	}
59	
60	/** Opaque, adapter-defined cursor (or null when nothing has been read yet). */
61	export type Cursor = string | null;
62	
63	export interface FetchResult {
64	  items: EvidenceItem[];
65	  cursor: Cursor;
66	}
67	
68	export interface Source {
69	  readonly name: string;
70	  /**
71	   * The producer identity this channel stamps on everything it captures. Separate
72	   * from `name` — which keys the cursor file — so that what a record says about its
73	   * origin is a declared member of {@link ACTORS} rather than whatever string an
74	   * adapter happened to name itself.
75	   */
76	  readonly actor: Actor;
77	  /** Return items new since `cursor`, plus the advanced cursor. Read-only. */
78	  fetchSince(cursor: Cursor): Promise<FetchResult>;
79	  /**
80	   * The cursor that covers `stored` and nothing else — what to persist when a fetch
81	   * was only partly stored.
82	   *
83	   * `fetchSince` returns one cursor for the whole batch, so persisting it after a
84	   * storage failure marks unstored items as delivered: the producer's report is
85	   * accepted and then lost, with no way to detect it or retry (W10). The framework
86	   * cannot repair that itself, because a cursor is opaque to it by design — only the
87	   * adapter knows whether its scheme can express "these three of five".
88	   *
89	   * **Returning `previous` unchanged is a correct implementation, and the required
90	   * one for a watermark cursor.** A high-water mark cannot name a subset; the honest
91	   * answer is to re-fetch the whole batch next time and let the store's own
92	   * idempotency drop the ones already written. The method is required rather than
93	   * optional so that a new adapter has to decide which of the two it is, in the file
94	   * where its cursor scheme is written.
95	   */
96	  advanceCursor(previous: Cursor, stored: EvidenceItem[]): Cursor;
97	}
98	
99	/**
100	 * What a channel's state file holds, beyond the cursor itself.
101	 *
102	 * **"Last fetched" and "last delivered" are separate fields, and silence is
103	 * computed only off the second.** A healthy poller over a dead channel advances
104	 * `lastFetchedAt` forever; conflating the two is precisely how a dead channel and
105	 * an idle one become the same observable — which is the failure S2 exists to end.
106	 *
107	 * Every stamp is the *ingesting surface's* clock, never an item's own
108	 * `timestamp`. A file mtime is producer-controlled, so `touch -d 2030` would let a
109	 * channel declare its own liveness. Same argument as stamping the actor at the
110	 * ingest site rather than reading it off the payload.
111	 *
112	 * The shape is a strict superset of the historical `{cursor}` file, and
113	 * {@link loadCursor} still reads `parsed.cursor`, so a state file written by any
114	 * earlier version loads unchanged. Such a record has no stamps at all and is
115	 * reported `undated` — a third answer that is neither `live` (a lie) nor `silent`
116	 * (which would flag every upgraded vault as dead on the day it upgraded).
117	 */
118	export interface CursorRecord {
119	  cursor: Cursor;
120	  /** First fetch on record. This is what dates a channel that has NEVER delivered. */
121	  firstFetchedAt?: string;
122	  /** Every completed fetch, item or not. Never used to decide silence. */
123	  lastFetchedAt?: string;
124	  /** The last fetch that actually STORED an item. This is what silence reads. */
125	  lastItemAt?: string;
126	  lastItemId?: string;
127	  itemsDelivered?: number;
128	}
129	
130	function stateDir(vaultDir: string): string {
131	  return path.join(path.resolve(vaultDir), ".ost-agent", "state");
132	}
133	
134	function cursorFile(vaultDir: string, name: string): string {
135	  // Fail-closed on the name, because the name is a path segment: a channel called
136	  // `../../etc` would put this write outside the state directory entirely. The
137	  // schema already refuses such a name, but the schema is not the only caller —
138	  // this is the last gate before the filesystem.
139	  if (!CHANNEL_NAME_PATTERN.test(name)) {
140	    throw new Error(
141	      `refusing to use "${name}" as a cursor name — a channel name must match ${CHANNEL_NAME_PATTERN} (it is a filename under .ost-agent/state/)`,
142	    );
143	  }
144	  return path.join(stateDir(vaultDir), `${name}.json`);
145	}
146	
147	/** The whole state file, or null when the channel has never been fetched. */
148	export function loadCursorRecord(vaultDir: string, name: string): CursorRecord | null {
149	  const p = cursorFile(vaultDir, name);
150	  if (!fs.existsSync(p)) return null;
151	  try {
152	    const parsed = JSON.parse(fs.readFileSync(p, "utf8")) as CursorRecord;
153	    if (typeof parsed !== "object" || parsed === null) return null;
154	    return { ...parsed, cursor: parsed.cursor ?? null };
155	  } catch {
156	    // Unreadable is not "never fetched": returning null here would let a corrupt
157	    // file read as a brand-new channel. It reads as one anyway for want of any
158	    // other honest answer, but the cursor half stays fail-closed — `loadCursor`
159	    // returns null, so the adapter re-offers everything and the store's own
160	    // idempotency drops what is already there.
161	    return null;
162	  }
163	}
164	
165	export function loadCursor(vaultDir: string, name: string): Cursor {
166	  return loadCursorRecord(vaultDir, name)?.cursor ?? null;
167	}
168	
169	/** What a completed fetch delivered, which is the only thing that dates a channel. */
170	export interface FetchOutcome {
171	  /** The items that actually reached storage. Empty is meaningful, not missing. */
172	  delivered: readonly EvidenceItem[];
173	  /** Injected so the stamps are deterministic under test. */
174	  now?: Date;
175	}
176	
177	/**
178	 * Persist a channel's cursor together with when it last fetched and last delivered.
179	 *
180	 * `outcome` is REQUIRED rather than optional, and that is the point: an optional
181	 * argument is one a call site can forget, and a forgotten one here means the
182	 * channel silently never dates itself and can never be reported silent. Making it
183	 * required puts the compiler in front of every call site.
184	 */
185	export function saveCursor(vaultDir: string, name: string, cursor: Cursor, outcome: FetchOutcome): void {
186	  const dir = stateDir(vaultDir);
187	  fs.mkdirSync(dir, { recursive: true });
188	  const previous = loadCursorRecord(vaultDir, name);
189	  const carried = {
190	    ...(previous?.lastItemAt ? { lastItemAt: previous.lastItemAt } : {}),
191	    ...(previous?.lastItemId ? { lastItemId: previous.lastItemId } : {}),
192	    ...(previous?.itemsDelivered ? { itemsDelivered: previous.itemsDelivered } : {}),
193	  };
194	
195	  // The three-argument fallback that lived here is GONE: `ost_ingest_inbox` — the
196	  // one caller that predated `outcome` — now passes `{ delivered: stored }` for
197	  // every channel it reads. It recorded the cursor and nothing else, which was the
198	  // only honest answer for a caller that said nothing about its outcome, and an
199	  // `undated` channel is never reported silent. Keeping it would leave a way to
200	  // write a cursor that permanently disables silence detection for that channel.
201	  const delivered = outcome.delivered;
202	  const at = (outcome.now ?? new Date()).toISOString();
203	  const record: CursorRecord = {
204	    cursor,
205	    firstFetchedAt: previous?.firstFetchedAt ?? at,
206	    lastFetchedAt: at,
207	    ...(delivered.length > 0
208	      ? {
209	          lastItemAt: at,
210	          lastItemId: delivered[delivered.length - 1].id,
211	          itemsDelivered: (previous?.itemsDelivered ?? 0) + delivered.length,
212	        }
213	      : carried),
214	  };
215	  fs.writeFileSync(cursorFile(vaultDir, name), JSON.stringify(record, null, 2), "utf8");
216	}
